// =====================================================================
// BullScope - Power Query (M)
// 1. Home -> Transform data -> Manage parameters -> New: DataFolder (Text),
//    value = full path of this repo's data\processed folder, ending with "\"
// 2. For each query below: New Source -> Blank query -> Advanced Editor,
//    paste the block, rename the query to the name in the header.
// Generated by scripts/build_bi_files.py
// =====================================================================

// ---------------- Stock Prices ----------------
let
    Source  = Csv.Document(File.Contents(DataFolder & "fact_stock_prices.csv"),
                [Delimiter = ",", Encoding = 65001, QuoteStyle = QuoteStyle.Csv]),
    Headers = Table.PromoteHeaders(Source, [PromoteAllScalars = true]),
    Keep    = Table.SelectColumns(Headers, {"date", "symbol", "open", "high", "low", "close", "volume", "daily_return", "turnover_cr", "buy_value_cr", "sell_value_cr"}),
    Blanks  = Table.ReplaceValue(Keep, "", null, Replacer.ReplaceValue, {"date", "open", "high", "low", "close", "volume", "daily_return", "turnover_cr", "buy_value_cr", "sell_value_cr"}),
    Typed   = Table.TransformColumnTypes(Blanks, {
        {"date", type date},
        {"symbol", type text},
        {"open", type number},
        {"high", type number},
        {"low", type number},
        {"close", type number},
        {"volume", type number},
        {"daily_return", type number},
        {"turnover_cr", type number},
        {"buy_value_cr", type number},
        {"sell_value_cr", type number}}, "en-US")
in
    Typed

